// Optimized, deferred JavaScript - no heavy blocking work
(function(){
  'use strict';

  // Lightweight stats population using DocumentFragment
  function populateStats(){
    const container=document.getElementById('stats');
    if(!container)return;
    const stats=[
      {n:'150+',l:'Destinations'},
      {n:'50k+',l:'Happy Travelers'},
      {n:'12',l:'Years Experience'},
      {n:'98%',l:'Satisfaction'}
    ];
    const frag=document.createDocumentFragment();
    stats.forEach(function(s){
      const div=document.createElement('div');
      div.className='stat-item';
      div.innerHTML='<div class="number">'+s.n+'</div><div class="label">'+s.l+'</div>';
      frag.appendChild(div);
    });
    container.appendChild(frag);
  }

  // Event delegation instead of many individual listeners
  function initEvents(){
    const cta=document.getElementById('ctaBtn');
    if(cta){
      cta.addEventListener('click',function(){
        alert('Welcome to TravelExplorer! Start your adventure today.');
      });
    }
    const form=document.getElementById('contactForm');
    if(form){
      form.addEventListener('submit',function(e){
        e.preventDefault();
        alert('Thank you for your message! We will get back to you soon.');
      });
    }
  }

  // Run when DOM is ready (defer already ensures this, but safe)
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){
      populateStats();
      initEvents();
    });
  }else{
    populateStats();
    initEvents();
  }
})();
